+  return {
+    search: request.search ?? "",
+    limit: request.limit,
+    cursor: request.cursor,
+    identity,
+  };
+}
+
+function validateResolveRequest(request) {
+  if (!isPlainObject(request)) throw new Error("invalid resolve request: not an object");
+  rejectUnknownKeys(request, new Set(["values", "context"]), "resolve request");
+  if (!Array.isArray(request.values) || request.values.length > MAX_RESOLVE_VALUES) {
+    throw new Error("invalid resolve request: values");
+  }
+  for (const value of request.values) {
+    if (typeof value !== "string" || !UUID_RE.test(value)) {
+      throw new Error("invalid resolve request: values item");
+    }
+  }
+  const identity = validateContext(request.context);
+  return { values: request.values, identity };
+}
+
+function requireTenantId(authorization) {
+  if (!isPlainObject(authorization) || typeof authorization.tenantId !== "string" || authorization.tenantId.length < 1) {
+    throw new Error("unauthorized: invalid tenant scope");
+  }
+  return authorization.tenantId;
+}
+
+function safeCustomerRows(rawCustomers, tenantId) {
+  if (!Array.isArray(rawCustomers)) throw new Error("invalid application customer records");
+  const rows = [];
+  for (const raw of rawCustomers) {
+    if (!isPlainObject(raw)) continue;
+    if (raw.tenantId !== tenantId) continue;
+    if (typeof raw.id !== "string" || !UUID_RE.test(raw.id)) continue;
+    if (typeof raw.name !== "string" || raw.name.length < 1 || raw.name.length > 256) continue;
+    rows.push({ id: raw.id, normalizedName: raw.name.normalize("NFKD"), label: raw.name });
+  }
+  return rows;
+}
+
+function compareRows(a, b) {
+  const nameCompare = a.normalizedName.localeCompare(b.normalizedName, "en");
+  if (nameCompare !== 0) return nameCompare;
+  return a.id.localeCompare(b.id);
+}
+
+function searchFingerprintOf(normalizedSearch) {
+  return createHash("sha256").update(normalizedSearch).digest("hex");
+}
+
+function signCursor(secret, payload) {
+  const payloadPart = Buffer.from(JSON.stringify(payload), "utf8").toString("base64url");
+  const signaturePart = createHmac("sha256", secret).update(payloadPart).digest("base64url");
+  return `${payloadPart}.${signaturePart}`;
+}
+
+function verifyCursor(secret, cursor) {
+  if (typeof cursor !== "string") throw new Error("malformed cursor");
+  const separatorIndex = cursor.lastIndexOf(".");
+  if (separatorIndex <= 0 || separatorIndex === cursor.length - 1) throw new Error("malformed cursor");
+  const payloadPart = cursor.slice(0, separatorIndex);
+  const signaturePart = cursor.slice(separatorIndex + 1);
+  if (!BASE64URL_RE.test(payloadPart) || !BASE64URL_RE.test(signaturePart)) throw new Error("malformed cursor");
+
+  const expectedSignature = createHmac("sha256", secret).update(payloadPart).digest();
+  const providedSignature = Buffer.from(signaturePart, "base64url");
+  if (
+    providedSignature.length !== expectedSignature.length ||
+    !timingSafeEqual(providedSignature, expectedSignature)
+  ) {
+    throw new Error("malformed cursor: signature mismatch");
+  }
+
+  let payload;
+  try {
+    payload = JSON.parse(Buffer.from(payloadPart, "base64url").toString("utf8"));
+  } catch {
+    throw new Error("malformed cursor: payload");
+  }
+  if (!isPlainObject(payload)) throw new Error("malformed cursor: payload");
+  return payload;
+}
+
+export async function query(request, application) {
+  const validated = validateQueryRequest(request);
+  const authorization = await application.authorize({
+    actorId: validated.identity.actorId,
+    targetId: validated.identity.targetId,
+  });
+  const tenantId = requireTenantId(authorization);
+
+  const normalizedSearch = validated.search.normalize("NFKD").toLowerCase();
+  const searchFingerprint = searchFingerprintOf(normalizedSearch);
+
+  let afterKey = null;
+  if (validated.cursor !== undefined) {
+    const payload = verifyCursor(application.cursorSecret, validated.cursor);
+    if (
+      payload.v !== CURSOR_VERSION ||
+      payload.tenantId !== tenantId ||
+      payload.search !== searchFingerprint ||
+      payload.limit !== validated.limit ||
+      !isPlainObject(payload.after) ||
+      typeof payload.after.name !== "string" ||
+      typeof payload.after.id !== "string"
+    ) {
+      throw new Error("malformed cursor: scope or fingerprint mismatch");
+    }
+    afterKey = { normalizedName: payload.after.name, id: payload.after.id };
+  }
+
+  const rows = safeCustomerRows(application.customers, tenantId);
+  const filtered = normalizedSearch.length === 0
+    ? rows
+    : rows.filter((row) => row.normalizedName.toLowerCase().includes(normalizedSearch));
+  filtered.sort(compareRows);
+
+  let startIndex = 0;
+  if (afterKey !== null) {
+    startIndex = filtered.findIndex((row) => compareRows(row, afterKey) > 0);
+    if (startIndex === -1) startIndex = filtered.length;
+  }
+
+  const page = filtered.slice(startIndex, startIndex + validated.limit);
+  const hasMore = startIndex + validated.limit < filtered.length;
+
+  const result = { items: page.map((row) => ({ value: row.id, label: row.label })) };
+  if (hasMore) {
+    const last = page[page.length - 1];
+    result.nextCursor = signCursor(application.cursorSecret, {
+      v: CURSOR_VERSION,
+      tenantId,
+      search: searchFingerprint,
+      limit: validated.limit,
+      after: { name: last.normalizedName, id: last.id },
+    });
+  }
+  return result;
+}
+
+export async function resolve(request, application) {
+  const validated = validateResolveRequest(request);
+  const authorization = await application.authorize({
+    actorId: validated.identity.actorId,
+    targetId: validated.identity.targetId,
+  });
+  const tenantId = requireTenantId(authorization);
+
+  const rows = safeCustomerRows(application.customers, tenantId);
+  const byId = new Map(rows.map((row) => [row.id.toLowerCase(), row]));
+
+  const results = validated.values.map((value) => {
+    const match = byId.get(value.toLowerCase());
+    return { value, item: match === undefined ? null : { value: match.id, label: match.label } };
+  });
+  return { results };
+}
+
+export const dataSource = Object.freeze({
+  definition: Object.freeze({
+    id: "customers",
+    label: "Customers",
+    capabilities: Object.freeze({
+      search: true,
+      pagination: "cursor",
+      resolve: true,
+      defaultLimit: DEFAULT_LIMIT,
+      maxLimit: MAX_LIMIT,
+    }),
+    contextSchema: dataSourceContextSchema,
+  }),
+  query,
+  resolve,
+});
